window.AUTH=window.AUTH||{};window.AUTH["19-161"]={"d":"19-161","id":"2019/19-161","n":"Department of Homeland Security v. Thuraissigiam","briefs":[{"k":"petitioner","label":"Brief of petitioners Department of Homeland Security, et al.","date":"2019-12-09","url":"https://www.supremecourt.gov/DocketPDF/19/19-161/125000/20191209192232041_19-161tsUnitedStates.pdf","side":"pet","n":84},{"k":"respondent","label":"Brief of respondent Vijayakumar Thuraissigiam","date":"2020-01-15","url":"https://www.supremecourt.gov/DocketPDF/19/19-161/128623/20200115105132945_19-161%20DHS%20v%20Thuraissigiam%20Brief%20for%20Respondent.pdf","side":"res","n":71},{"k":"reply","label":"Reply of petitioners Department of Homeland Security, et al.","date":"2020-02-14","url":"https://www.supremecourt.gov/DocketPDF/19/19-161/133167/20200214174812481_19-161rbUnitedStates.pdf","side":"pet","n":46}],"opinion":"https://www.supremecourt.gov/opinions/preliminaryprint/591US1PP_web.pdf#page=113","tr":true,"items":[{"t":"case","label":"American Immigration Lawyers Ass’n v. Reno: 18 F. Supp. 2d 38 (D.D.C. 1998), aff ’d","cite":"199 F.3d 1352","y":2000,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/199/1352/","by":{"0":"44"},"q":[{"src":"argument","who":"Mr. Gelernt","text":"Even in regular immigration proceedings, pro se from an immigration judge to the Board of Immigration Appeals is only three percent. It's much harder at the border."}]},{"t":"case","label":"Boumediene v. Bush","cite":"553 U.S. 723","y":2008,"id":"2007/06-1195","sc":1,"by":{"0":"passim","1":"passim, 30, 30","2":"5, 15, 16, 20, 21"},"q":[{"src":"brief","b":0,"text":"the Suspension Clause entitles the [habeas] petitioner to a meaningful opportunity to demonstrate that he is being held pursuant to the erroneous application or interpretation of relevant law.","cite":"553 U.S. at 779"},{"src":"brief","b":0,"text":"foreclose[d] the possibility that the protections of the Suspension Clause have expanded","cite":"553 U.S. 723, 746"},{"src":"brief","b":1,"text":"where there had been little or no previous judicial review of the cause for detention.","cite":"553 U.S. at 780"},{"src":"brief","b":1,"text":"the King’s prerogative to inquire into the authority of a jailer to hold a prisoner,","cite":"553 U.S. at 741"},{"src":"brief","b":2,"text":"had never set foot in the United States.","cite":"553 U.S. at 755"},{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"when the Constitution was drafted and ratifed.","cite":"553 U. S. 723, 746"},{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"were considered agents of the Crown, designed to assist the King in the exercise of his power.","cite":"553 U. S., at 740"},{"src":"argument","who":"Justice Breyer","text":"But Boumediene says that the detainee has the right to go into court under habeas and to make his claim. Now the judge, which Boumediene didn't really talk about, may have tremendous discretion, may not, may say it's up to the Executive Branch, may say all the things that you said."},{"src":"argument","who":"Mr. Kneedler","text":"And as Boumediene itself said, habeas is a flexible, adaptable remedy. And what Congress did here was tailor it to the specific circumstances of expedited removal."},{"src":"argument","who":"Mr. Gelernt","text":"What this Court said in Boumediene is the Court doesn't have to, in habeas, permit -- permit full release. It can give the government another chance."}]},{"t":"case","label":"Carlson v. Landon","cite":"342 U.S. 524","y":1952,"id":"scdb/1951-054","sc":1,"by":{"0":"22","1":"16"}},{"t":"case","label":"Castro v. U.S. Dep’t of Homeland Sec.: 163 F. Supp. 3d 157 (E.D. Pa.), aff ’d","cite":"835 F.3d 422","y":2016,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/835/422/","by":{"0":"45, 46","1":"37","2":"19"},"q":[{"src":"brief","b":0,"text":"suggests strongly that the Suspension Clause does not require judicial review of purely factual determinations or mixed fact and law determinations made in the context of alien exclusion.","cite":"835 F.3d 422"}]},{"t":"case","label":"Clark v. Martinez","cite":"543 U.S. 371","y":2005,"id":"2004/03-878","sc":1,"by":{"0":"3","1":"39, 39"}},{"t":"case","label":"Dimova v. Holder","cite":"783 F.3d 30","y":2015,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/783/30/","by":{"0":"26"}},{"t":"case","label":"Fay v. Noia","cite":"372 U.S. 391","y":1963,"id":"1962/84","sc":1,"by":{"0":"23","1":"36"},"q":[{"src":"brief","b":0,"text":"is simply a mode of procedure.","cite":"372 U.S. 391, 401"}]},{"t":"case","label":"Felker v. Turpin","cite":"518 U.S. 651","y":1996,"id":"1995/95-8836","sc":1,"by":{"0":"28","1":"25"},"q":[{"src":"brief","b":0,"text":"judgments about the proper scope of the writ are ‘normally for Congress to make.’","cite":"518 U.S. 651, 664"}]},{"t":"case","label":"Galvan v. Press","cite":"347 U.S. 522","y":1954,"id":"scdb/1953-075","sc":1,"by":{"0":"21"}},{"t":"case","label":"Gegiow v. Uhl","cite":"239 U.S. 3","y":1915,"id":"scdb/1915-065","sc":1,"by":{"0":"39","1":"15, 21, 22, 24","2":"12, 13"},"q":[{"src":"brief","b":2,"text":"courts are not forbidden by the statute to consider whether the reasons [for deportation], when they are given, agree with the requirements of the act. * * * The conclusiveness of the decisions of immigration officers under [the finality statute] is conclusiveness upon matters of fact.","cite":"239 U.S. 3, 9"},{"src":"argument","who":"Mr. Gelernt","text":"That's the Gegiow case, Ekiu. All of those finality era cases were looking at whether they fell within the statute. There were restrictions."}]},{"t":"case","label":"Hamama v. Adducci","cite":"912 F.3d 869","y":2018,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/912/869/","by":{"0":"30"}},{"t":"case","label":"Hamdi v. Rumsfeld","cite":"542 U.S. 507","y":2004,"id":"2003/03-6696","sc":1,"by":{"0":"23"}},{"t":"case","label":"Harisiades v. Shaughnessy","cite":"342 U.S. 580","y":1952,"id":"scdb/1951-056","sc":1,"by":{"0":"21"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"open door to the immigrant was the . . . federal policy.","cite":"342 U. S. 580, 588, n. 15"}]},{"t":"case","label":"Heikkila v. Barber","cite":"345 U.S. 229","y":1953,"id":"scdb/1952-068","sc":1,"by":{"0":"23, 39","1":"passim, 17","2":"12"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"Because of [the Suspension] Clause, some `judicial intervention in deportation cases' is unquestionably `required by the Constitution.'","cite":"345 U. S., at 235"},{"src":"argument","who":"Mr. Gelernt","text":"One is Accardi, decided the year after Heikkila v. Barber said the only review under this regime is that which is required by the Constitution."},{"src":"argument","who":"Mr. Gelernt","text":"One is in the Martinez brief, which was -- Martinez was the companion case to Heikkila v. Barber -- and I would just refer the Court to the -- to the SG's brief in that case -- the government was very clear that the Suspension Clause requires some review, that the finality era statutes limited review to the constitutional requirement."}]},{"t":"case","label":"INS v. Cardoza-Fonseca","cite":"480 U.S. 421","y":1987,"id":"1986/85-782","sc":1,"by":{"0":"34"}},{"t":"case","label":"INS v. St. Cyr","cite":"533 U.S. 289","y":2001,"id":"2000/00-767","sc":1,"by":{"0":"passim","1":"passim","2":"11, 15"},"q":[{"src":"brief","b":0,"text":"the Suspension Clause protects the writ as it existed in 1789.","cite":"533 U.S. at 301"},{"src":"brief","b":0,"text":"one-way ratchet that enshrines in the Constitution every grant of habeas jurisdiction","cite":"533 U.S. at 342"},{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"[t]he Privilege of the Writ of Habeas Corpus shall not be suspended, unless when in Cases of Rebellion or Invasion the public Safety may require it.","cite":"533 U. S. 289"},{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"[i]mplications from statu- 24 The Governor of Hawaii suspended habeas, with President Roosevelt's approval, after the attack on Pearl Harbor. See Duncan v. Kahanamoku, 327 U. S. 304, 307–308, 324 (1946). tory text or legislative history are not suffcient to repeal habeas jurisdiction.","cite":"533 U. S., at 299"}]},{"t":"case","label":"Jennings v. Rodriguez","cite":"138 S. Ct. 830","y":2018,"id":"2017/15-1204","sc":1,"by":{"0":"34"}},{"t":"case","label":"Kaplan v. Tod","cite":"267 U.S. 228","y":1925,"id":"scdb/1924-095","sc":1,"by":{"0":"27"}},{"t":"case","label":"Kleindienst v. Mandel","cite":"408 U.S. 753","y":1972,"id":"1971/71-16","sc":1,"by":{"0":"21","2":"4"},"q":[{"src":"brief","b":0,"text":"[T]he Court’s general reaffirmations of this principle have been legion.","cite":"408 U.S. 753, 765-766"},{"src":"brief","b":2,"text":"the Court’s general reaffirmations of this principle have been legion.","cite":"408 U.S. 753, 765-766"}]},{"t":"case","label":"Kucana v. Holder","cite":"558 U.S. 233","y":2010,"id":"2009/08-911","sc":1,"by":{"0":"5"},"q":[{"src":"brief","b":0,"text":"expedite removal of aliens lacking a legal basis to remain in the United States.","cite":"558 U.S. 233, 249"}]},{"t":"case","label":"Kwong Hai Chew v. Colding","cite":"344 U.S. 590","y":1953,"id":"scdb/1952-047","sc":1,"by":{"0":"25","1":"passim, 39","2":"7"}},{"t":"case","label":"Landon v. Plasencia","cite":"459 U.S. 21","y":1982,"id":"1982/81-129","sc":1,"by":{"0":"15, 16, 21, 23, 25, 33","2":"3, 4, 7"},"q":[{"src":"brief","b":0,"text":"that an alien seeking initial admission to the United States requests a privilege and has no constitutional rights regarding his application, for the power to admit or exclude aliens is a sovereign prerogative.","cite":"459 U.S. 21, 32"},{"src":"brief","b":0,"text":"has no constitutional rights regarding his application.","cite":"459 U.S. 21, 32"}]},{"t":"case","label":"Lonchar v. Thomas","cite":"517 U.S. 314","y":1996,"id":"1995/95-5015","sc":1,"by":{"0":"28"}},{"t":"case","label":"Make the Road N.Y. v. McAleenan","cite":"2019 WL 4738070","y":2019,"court":"D.D.C. Sept. 27","by":{"0":"6"}},{"t":"case","label":"Martinez v. Attorney Gen.","cite":"693 F.3d 408","y":2012,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/693/408/","by":{"0":"4"},"q":[{"src":"brief","b":0,"text":"noncitizens who had entered without inspection could take advantage of the greater procedural and substantive rights afforded in deportation proceedings, while non-citizens who actually presented themselves to authorities for inspection were restrained by more summary exclusion proceedings.","cite":"693 F.3d 408, 413 n.5"}]},{"t":"case","label":"Mathews v. Eldridge","cite":"424 U.S. 319","y":1976,"id":"1975/74-204","sc":1,"by":{"0":"19, 41, 46, 48","2":"22"}},{"t":"case","label":"Munaf v. Geren","cite":"553 U.S. 674","y":2008,"id":"2007/06-1666","sc":1,"by":{"0":"17, 28, 29, 30, 46","1":"32","2":"16, 18, 19, 20"},"q":[{"src":"brief","b":0,"text":"Habeas is at its core a remedy for unlawful executive detention.","cite":"553 U.S. 674, 693"},{"src":"brief","b":0,"text":"remedy for such detention is, of course, release.","cite":"553 U.S. at 693"},{"src":"brief","b":2,"text":"remedy for such detention is, of course, release.","cite":"553 U.S. 674, 693"},{"src":"brief","b":2,"text":"to be addressed by the political branches, not the Judiciary.","cite":"553 U.S. at 700"},{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"a remedy for unlawful executive detention.","cite":"553 U. S., at 693"},{"src":"argument","who":"Mr. Kneedler","text":"This Court's unanimous decision in Munaf is very much on point in that respect. The Court there held that it is not for a court in habeas corpus, even involving a citizen, to review the conditions of the place where the person would be sent."},{"src":"argument","who":"Mr. Kneedler","text":"Even in the context of whether an alien is excludable, that was not reviewable under the long line of this Court's decisions during the finality era, but, in addition, because of the nature of the -- of the screening involved here concerning fears of conditions in another country, a situation in which, again, this Court unanimously in Munaf held was not necessary -- did not have to be reviewed under habeas corpus for a United States citizen to --"},{"src":"argument","who":"Mr. Kneedler","text":"-- if someone is sought for extradition purposes and they are in the United States and -- and they are claiming don't send me to another country that has requested my extradition because of what the procedures will be there, what treatment I will be -- I will receive there, the rule of non-inquiry has sustained the ability of -- of Congress not to provide for judicial review. And that was true in Munaf --"}]},{"t":"case","label":"Nishimura Ekiu v. United States","cite":"142 U.S. 651","y":1892,"id":"scdb/1891-092","sc":1,"by":{"0":"22, 24, 39","1":"passim","2":"8, 13, 14"},"q":[{"src":"brief","b":0,"text":"supervision of the admission of aliens into the United States","cite":"142 U.S. 651, 659-660"},{"src":"brief","b":0,"text":"foreigners who have never been naturalized, nor acquired any domicil[e] or residence within the United States, nor even been admitted into the country pursuant to law.","cite":"142 U.S. at 660"},{"src":"brief","b":2,"text":"be permitted to enter, in opposition to","cite":"142 U.S. 651, 660"},{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"the political department of the government","cite":"142 U. S., at 659"},{"src":"argument","who":"Mr. Gelernt","text":"That's the Nishimura Ekiu case in 1892. It was the Chin Yow case a few years later. And even before Ekiu was Jung Ah Lung. For the next 60 years in finality, reviewed those cases."}]},{"t":"case","label":"Preiser v. Rodriguez","cite":"411 U.S. 475","y":1973,"id":"1972/71-1369","sc":1,"by":{"0":"28","2":"16"},"q":[{"src":"brief","b":2,"text":"that the essence of habeas corpus is an attack by a person in custody upon the legality of that custody.","cite":"411 U.S. 475, 484"},{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"is the appropriate remedy to ascertain . . . whether any person is rightfully in confnement or not.","cite":"411 U. S. 475, 484"}]},{"t":"case","label":"Shaughnessy v. United States ex rel. Mezei","cite":"345 U.S. 206","y":1953,"id":"scdb/1952-067","sc":1,"by":{"0":"21, 27, 31, 40","1":"passim","2":"4, 13"}},{"t":"case","label":"Soriano v. Gonzales","cite":"484 F.3d 318","y":2007,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/484/318/","by":{"0":"26"}},{"t":"case","label":"Swain v. Pressley","cite":"430 U.S. 372","y":1977,"id":"1976/75-811","sc":1,"by":{"0":"19, 40"}},{"t":"case","label":"United States v. Aslam","cite":"936 F.2d 751","y":1991,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/936/751/","by":{"0":"26"}},{"t":"case","label":"United States v. Hayman","cite":"342 U.S. 205","y":1952,"id":"scdb/1951-024","sc":1,"by":{"0":"40"}},{"t":"case","label":"United States v. Martinez-Fuerte","cite":"428 U.S. 543","y":1976,"id":"1975/74-1560","sc":1,"by":{"0":"26","1":"41"}},{"t":"case","label":"United States v. Verdugo-Urquidez","cite":"494 U.S. 259","y":1990,"id":"1989/88-1353","sc":1,"by":{"0":"25","1":"44"}},{"t":"case","label":"United States ex rel. Knauff v. Shaughnessy","cite":"338 U.S. 537","y":1950,"id":"scdb/1949-033","sc":1,"by":{"0":"17, 21","1":"passim","2":"3, 4, 5, 7, 13"},"q":[{"src":"brief","b":0,"text":"[w]hatever the procedure authorized by Congress is, it is due process as far as an alien denied entry is concerned.","cite":"338 U.S. 537, 544"},{"src":"brief","b":0,"text":"Congress supplies the conditions of the privilege of entry into the United States.","cite":"338 U.S. 537, 543"},{"src":"brief","b":2,"text":"[w]hatever the procedure authorized by Congress is, it is due process as far as an alien denied entry is concerned.","cite":"338 U.S. 537, 544"},{"src":"argument","who":"Mr. Gelernt","text":"So you take Mizai and Knauff, which established no procedural due process for people at the ports. They expressly held that they didn't have procedural due process, but then they went on in habeas to review the statutory and regulatory claims."}]},{"t":"case","label":"United States ex rel. Turner v. Williams","cite":"194 U.S. 279","y":1904,"id":"scdb/1903-104","sc":1,"by":{"0":"25","2":"11"}},{"t":"case","label":"Vartelas v. Holder","cite":"566 U.S. 257","y":2012,"id":"2011/10-1211","sc":1,"by":{"0":"4, 5","1":"42"},"q":[{"src":"brief","b":0,"text":"established two types of proceedings in which aliens can be denied the hospitality of the United States: deportation hearings and exclusion hearings.","cite":"566 U.S. 257, 261"}]},{"t":"case","label":"Wong Yang Sung v. McGrath","cite":"339 U.S. 33","y":1950,"id":"scdb/1949-048","sc":1,"by":{"0":"24","2":"7, 9"},"q":[{"src":"brief","b":0,"text":"deportation statute must provide a hearing at least for aliens who had not entered clandestinely and who had been here some time even if illegally.","cite":"339 U.S. 33, 49-50"}]},{"t":"case","label":"Yamataya v. Fisher","cite":"189 U.S. 86","y":1903,"id":"scdb/1902-102","sc":1,"by":{"0":"17, 23, 24, 27, 46","1":"39","2":"7, 9"},"q":[{"src":"brief","b":0,"text":"who has entered the country clandestinely, and who has been here for too brief a period to have become, in any real sense, a part of our population.","cite":"189 U.S. 86, 100"},{"src":"brief","b":0,"text":"to have become, in any real sense, a part of our population.","cite":"189 U.S. at 100"}]},{"t":"case","label":"Zakonaite v. Wolf","cite":"226 U.S. 272","y":1912,"id":"scdb/1912-027","sc":1,"by":{"0":"22, 23, 45","1":"16"}},{"t":"const","label":"Article I, Section 9, Clause 2","clauses":[["habeas","Suspension Clause (Habeas Corpus)"]],"text":"The Privilege of the Writ of Habeas Corpus shall not be suspended, unless when in Cases of Rebellion or Invasion the public Safety may require it.","by":{"0":"35"}},{"t":"law","label":"Pub. L. No. 104-208","url":"https://www.govinfo.gov/link/plaw/104/public/208","by":{"0":"4"}},{"t":"usc","label":"8 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/8/1101","subs":["(a)(13)(1988)","(a)(42)(A)"],"stext":{"head":"§1101. Definitions","paras":[[0,"(a) As used in this chapter—"],[0,"(1) The term \"administrator\" means the official designated by the Secretary of State pursuant to section 1104(b) of this title."],[0,"(2) The term \"advocates\" includes, but is not limited to, advises, recommends, furthers by overt act, and admits belief in."],[0,"(3) The term \"alien\" means any person not a citizen or national of the United States."],[0,"(4) The term \"application for admission\" has reference to the application for admission into the United States and not to the application for the issuance of an immigrant or nonimmigrant visa."],[0,"(5) The term \"Attorney General\" means the Attorney General of the United States."],[0,"(6) The term \"border crossing identification card\" means a document of identity bearing that designation issued to an alien who is lawfully admitted for permanent residence, or to an alien who is a resident in foreign contiguous territory, by a consular officer or an immigration officer for the purpose of crossing over the borders between the United States and foreign contiguous territory in accordance with such conditions for its issuance and use as may be prescribed by regulations. Such regulations shall provide that (A) each such document include a biometric identifier (such as the fingerprint or handprint of the alien) that is machine readable and (B) an alien presenting a border crossing identification card is not permitted to cross over the border into the United States unless the biometric identifier contained on the card matches the appropriate biometric characteristic of the alien."],[0,"(7) The term \"clerk of court\" means a clerk of a naturalization court."],[0,"(8) The terms \"Commissioner\" and \"Deputy Commissioner\" mean the Commissioner of Immigration and Naturalization and a Deputy Commissioner of Immigration and Naturalization, respectively."],[0,"(9) The term \"consular officer\" means any consular, diplomatic, or other officer or employee of the United States designated under regulations prescribed under authority contained in this chapter, for the purpose of issuing immigrant or nonimmigrant visas or, when used in subchapter III, for the purpose of adjudicating nationality."],[0,"(10) The term \"crewman\" means a person serving in any capacity on board a vessel or aircraft."],[0,"(11) The term \"diplomatic visa\" means a nonimmigrant visa bearing that title and issued to a nonimmigrant in accordance with such regulations as the Secretary of State may prescribe."],[0,"(12) The term \"doctrine\" includes, but is not limited to, policies, practices, purposes, aims, or procedures."],[0,"(13)(A) The terms \"admission\" and \"admitted\" mean, with respect to an alien, the lawful entry of the alien into the United States after inspection and authorization by an immigration officer."],[0,"(B) An alien who is paroled under section 1182(d)(5) of this title or permitted to land temporarily as an alien crewman shall not be considered to have been admitted."],[0,"(C) An alien lawfully admitted for permanent residence in the United States shall not be regarded as seeking an admission into the United States for purposes of the immigration laws unless the alien—"],[1,"(i) has abandoned or relinquished that status,"],[1,"(ii) has been absent from the United States for a continuous period in excess of 180 days,"],[1,"(iii) has engaged in illegal activity after having departed the United States,"],[1,"(iv) has departed from the United States while under legal process seeking removal of the alien from the United States, including removal proceedings under this chapter and extradition proceedings,"],[1,"(v) has committed an offense identified in section 1182(a)(2) of this title, unless since such offense the alien has been granted relief under section 1182(h) or 1229b(a) of this title, or"],[1,"(vi) is attempting to enter at a time or place other than as designated by immigration officers or has not been admitted to the United States after inspection and authorization by an immigration officer."],[0,"(14) The term \"foreign state\" includes outlying possessions of a foreign state, but self-governing dominions or territories under mandate or trusteeship shall be regarded as separate foreign states."],[0,"(15) The term \"immigrant\" means every alien except an alien who is within one of the following classes of nonimmigrant aliens—"],[1,"(A)(i) an ambassador, public minister, or career diplomatic or consular officer who has been accredited by a foreign government, recognized de jure by the United States and who is accepted by the President or by the Secretary of State, and the members of the alien's immediate family;"],[1,"(ii) upon a basis of reciprocity, other officials and employees who have been accredited by a foreign government recognized de jure by the United States, who are accepted by the Secretary of State, and the members of their immediate families; and"],[1,"(iii) upon a basis of reciprocity, attendants, servants, personal employees, and members of their immediate families, of the officials and employees who have a nonimmigrant status under (i) and (ii) above;"],[1,"(B) an alien (other than one coming for the purpose of study or of performing skilled or unskilled labor or as a representative of foreign press, radio, film, or other foreign information media coming to engage in such vocation) having a residence in a foreign country which he has no intention of abandoning and who is visiting the United States temporarily for business or temporarily for pleasure;"],[1,"(C)(i) an alien in immediate and continuous transit through the United States, for a period not to exceed 29 days;"],[1,"(ii) an alien who qualifies as a person entitled to pass in transit to and from the United Nations Headquarters District (as defined in section 4309a(e) of title 22) and foreign countries, under the provisions of paragraphs (3), (4), and (5) of section 11 of the Agreement regarding the Headquarters of the United Nations, done at Lake Success June 26, 1947 (61 Stat. 758); or"],[1,"(iii) an alien passing in transit through the United States to board a vessel on which the alien will perform, or to disembark from a vessel on which the alien performed, ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, for a period not to exceed 180 days;"],[1,"(D)(i) an alien crewman serving in good faith as such in a capacity required for normal operation and service on board a vessel, as defined in section 1288(a) of this title (other than a fishing vessel having its home port or an operating base in the United States), or aircraft, who intends to land temporarily and solely in pursuit of his calling as a crewman and to depart from the United States with the vessel or aircraft on which he arrived or some other vessel or aircraft;"],[1,"(ii) an alien crewman serving in good faith as such in any capacity required for normal operations and service aboard a fishing vessel having its home port or an operating base in the United States who intends to land temporarily in Guam or the Commonwealth of the Northern Mariana Islands and solely in pursuit of his calling as a crewman and to depart from Guam or the Commonwealth of the Northern Mariana Islands with the vessel on which he arrived; or"],[1,"(iii) an alien crewman performing ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, who intends to land temporarily solely in pursuit of the alien's responsibilities as a crewman and to depart from the United States on the vessel on which the alien arrived or on another vessel or aircraft, for a period not to exceed 180 days;"],[1,"(E) an alien entitled to enter the United States under and in pursuance of the provisions of a treaty of commerce and navigation between the United States and the foreign state of which the alien is a national (or, in the case of an alien who acquired the relevant nationality through a financial investment and who has not previously been granted status under this subparagraph, the foreign state of which the alien is a national and in which the alien has been domiciled for a continuous period of not less than 3 years at any point before applying for a nonimmigrant visa under this subparagraph), and the spouse and children of any such alien if accompanying or following to join such alien; (i) solely to carry on substantial trade, including trade in services or trade in technology, principally between the United States and the foreign state of which the alien is a national; (ii) solely to develop and direct the operations of an enterprise in which the alien has invested, or of an enterprise in which the alien is actively in the process of investing, a substantial amount of capital; or (iii) solely to perform services in a specialty occupation in the United States if the alien is a national of the Commonwealth of Australia and with respect to whom the Secretary of Labor determines and certifies to the Secretary of Homeland Security and the Secretary of State that the intending employer has filed with the Secretary of Labor an attestation under section 1182(t)(1) of this title;"],[1,"(F)(i) an alien having a residence in a foreign country which he has no intention of abandoning, who is a bona fide student qualified to pursue a full course of study and who seeks to enter the United States temporarily and solely for the purpose of pursuing such a course of study consistent with section 1184(l) 1 of this title at an established college, university, seminary, conservatory, academic high school, elementary school, or other academic institution or in an accredited language training program in the United States, particularly designated by him and approved by the Attorney General after consultation with the Secretary of Education, which institution or place of study shall have agreed to report to the Attorney General the termination of attendance of each nonimmigrant student, and if any such institution of learning or place of study fails to make reports promptly the approval shall be withdrawn, (ii) the alien spouse and minor children of any alien described in clause (i) if accompanying or following to join such an alien, and (iii) an alien who is a national of Canada or Mexico, who maintains actual residence and place of abode in the country of nationality, who is described in clause (i) except that the alien's qualifications for and actual course of study may be full or part-time, and who commutes to the United States institution or place of study from Canada or Mexico;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1101?type=usc&year=mostrecent&link-type=html"},"by":{"0":"4, 35, 4, 3","1":"6","2":"23"},"q":[{"src":"brief","b":0,"text":"Under this regime, ‘entry’ into the United States was defined as ‘any coming of an alien into the United States, from a foreign port or place.’","cite":"8 U.S.C. 1101(a)(13)"},{"src":"brief","b":0,"text":"because of persecution or a well-founded fear of persecution on account of race, religion, nationality, membership in a particular social group, or political opinion.","cite":"8 U.S.C. 1101(a)(42)(A)"}]},{"t":"usc","label":"8 U.S.C. § 1158","url":"https://www.law.cornell.edu/uscode/text/8/1158","subs":["(a)","(b)(1)(A)","(a)(1)"],"stext":{"head":"§1158. Asylum","paras":[[0,"(a) Authority to apply for asylum"],[0,"(1) In general"],[1,"Any alien who is physically present in the United States or who arrives in the United States (whether or not at a designated port of arrival and including an alien who is brought to the United States after having been interdicted in international or United States waters), irrespective of such alien's status, may apply for asylum in accordance with this section or, where applicable, section 1225(b) of this title."],[0,"(2) Exceptions"],[0,"(A) Safe third country"],[2,"Paragraph (1) shall not apply to an alien if the Attorney General determines that the alien may be removed, pursuant to a bilateral or multilateral agreement, to a country (other than the country of the alien's nationality or, in the case of an alien having no nationality, the country of the alien's last habitual residence) in which the alien's life or freedom would not be threatened on account of race, religion, nationality, membership in a particular social group, or political opinion, and where the alien would have access to a full and fair procedure for determining a claim to asylum or equivalent temporary protection, unless the Attorney General finds that it is in the public interest for the alien to receive asylum in the United States."],[0,"(B) Time limit"],[2,"Subject to subparagraph (D), paragraph (1) shall not apply to an alien unless the alien demonstrates by clear and convincing evidence that the application has been filed within 1 year after the date of the alien's arrival in the United States."],[0,"(C) Previous asylum applications"],[2,"Subject to subparagraph (D), paragraph (1) shall not apply to an alien if the alien has previously applied for asylum and had such application denied."],[0,"(D) Changed circumstances"],[2,"An application for asylum of an alien may be considered, notwithstanding subparagraphs (B) and (C), if the alien demonstrates to the satisfaction of the Attorney General either the existence of changed circumstances which materially affect the applicant's eligibility for asylum or extraordinary circumstances relating to the delay in filing an application within the period specified in subparagraph (B)."],[0,"(E) Applicability"],[2,"Subparagraphs (A) and (B) shall not apply to an unaccompanied alien child (as defined in section 279(g) of title 6)."],[0,"(3) Limitation on judicial review"],[1,"No court shall have jurisdiction to review any determination of the Attorney General under paragraph (2)."],[0,"(b) Conditions for granting asylum"],[0,"(1) In general"],[0,"(A) Eligibility"],[2,"The Secretary of Homeland Security or the Attorney General may grant asylum to an alien who has applied for asylum in accordance with the requirements and procedures established by the Secretary of Homeland Security or the Attorney General under this section if the Secretary of Homeland Security or the Attorney General determines that such alien is a refugee within the meaning of section 1101(a)(42)(A) of this title."],[0,"(B) Burden of proof"],[0,"(i) In general"],[3,"The burden of proof is on the applicant to establish that the applicant is a refugee, within the meaning of section 1101(a)(42)(A) of this title. To establish that the applicant is a refugee within the meaning of such section, the applicant must establish that race, religion, nationality, membership in a particular social group, or political opinion was or will be at least one central reason for persecuting the applicant."],[0,"(ii) Sustaining burden"],[3,"The testimony of the applicant may be sufficient to sustain the applicant's burden without corroboration, but only if the applicant satisfies the trier of fact that the applicant's testimony is credible, is persuasive, and refers to specific facts sufficient to demonstrate that the applicant is a refugee. In determining whether the applicant has met the applicant's burden, the trier of fact may weigh the credible testimony along with other evidence of record. Where the trier of fact determines that the applicant should provide evidence that corroborates otherwise credible testimony, such evidence must be provided unless the applicant does not have the evidence and cannot reasonably obtain the evidence."],[0,"(iii) Credibility determination"],[3,"Considering the totality of the circumstances, and all relevant factors, a trier of fact may base a credibility determination on the demeanor, candor, or responsiveness of the applicant or witness, the inherent plausibility of the applicant's or witness's account, the consistency between the applicant's or witness's written and oral statements (whenever made and whether or not under oath, and considering the circumstances under which the statements were made), the internal consistency of each such statement, the consistency of such statements with other evidence of record (including the reports of the Department of State on country conditions), and any inaccuracies or falsehoods in such statements, without regard to whether an inconsistency, inaccuracy, or falsehood goes to the heart of the applicant's claim, or any other relevant factor. There is no presumption of credibility, however, if no adverse credibility determination is explicitly made, the applicant or witness shall have a rebuttable presumption of credibility on appeal."],[0,"(2) Exceptions"],[0,"(A) In general"],[2,"Paragraph (1) shall not apply to an alien if the Attorney General determines that—"],[3,"(i) the alien ordered, incited, assisted, or otherwise participated in the persecution of any person on account of race, religion, nationality, membership in a particular social group, or political opinion;"],[3,"(ii) the alien, having been convicted by a final judgment of a particularly serious crime, constitutes a danger to the community of the United States;"],[3,"(iii) there are serious reasons for believing that the alien has committed a serious nonpolitical crime outside the United States prior to the arrival of the alien in the United States;"],[3,"(iv) there are reasonable grounds for regarding the alien as a danger to the security of the United States;"],[3,"(v) the alien is described in subclause (I), (II), (III), (IV), or (VI) of section 1182(a)(3)(B)(i) of this title or section 1227(a)(4)(B) of this title (relating to terrorist activity), unless, in the case only of an alien described in subclause (IV) of section 1182(a)(3)(B)(i) of this title, the Attorney General determines, in the Attorney General's discretion, that there are not reasonable grounds for regarding the alien as a danger to the security of the United States; or"],[3,"(vi) the alien was firmly resettled in another country prior to arriving in the United States."],[0,"(B) Special rules"],[0,"(i) Conviction of aggravated felony"],[3,"For purposes of clause (ii) of subparagraph (A), an alien who has been convicted of an aggravated felony shall be considered to have been convicted of a particularly serious crime."],[0,"(ii) Offenses"],[3,"The Attorney General may designate by regulation offenses that will be considered to be a crime described in clause (ii) or (iii) of subparagraph (A)."],[0,"(C) Additional limitations"],[2,"The Attorney General may by regulation establish additional limitations and conditions, consistent with this section, under which an alien shall be ineligible for asylum under paragraph (1)."],[0,"(D) No judicial review"],[2,"There shall be no judicial review of a determination of the Attorney General under subparagraph (A)(v)."],[0,"(3) Treatment of spouse and children"],[0,"(A) In general"],[2,"A spouse or child (as defined in section 1101(b)(1)(A), (B), (C), (D), or (E) of this title) of an alien who is granted asylum under this subsection may, if not otherwise eligible for asylum under this section, be granted the same status as the alien if accompanying, or following to join, such alien."],[0,"(B) Continued classification of certain aliens as children"],[2,"An unmarried alien who seeks to accompany, or follow to join, a parent granted asylum under this subsection, and who was under 21 years of age on the date on which such parent applied for asylum under this section, shall continue to be classified as a child for purposes of this paragraph and section 1159(b)(3) of this title, if the alien attained 21 years of age after such application was filed but while it was pending."],[0,"(C) Initial jurisdiction"],[2,"An asylum officer (as defined in section 1225(b)(1)(E) of this title) shall have initial jurisdiction over any asylum application filed by an unaccompanied alien child (as defined in section 279(g) of title 6), regardless of whether filed in accordance with this section or section 1225(b) of this title."],[0,"(c) Asylum status"],[0,"(1) In general"],[1,"In the case of an alien granted asylum under subsection (b), the Attorney General—"],[2,"(A) shall not remove or return the alien to the alien's country of nationality or, in the case of a person having no nationality, the country of the alien's last habitual residence;"],[2,"(B) shall authorize the alien to engage in employment in the United States and provide the alien with appropriate endorsement of that authorization; and"],[2,"(C) may allow the alien to travel abroad with the prior consent of the Attorney General."],[0,"(2) Termination of asylum"],[1,"Asylum granted under subsection (b) does not convey a right to remain permanently in the United States, and may be terminated if the Attorney General determines that—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1158?type=usc&year=mostrecent&link-type=html"},"by":{"0":"3, 3","1":"43","2":"5"}},{"t":"usc","label":"8 U.S.C. § 1182","url":"https://www.law.cornell.edu/uscode/text/8/1182","subs":["(a)(6)(C)","(a)(6)(E)(i)","(a)(7)"],"stext":{"head":"§1182. Inadmissible aliens","paras":[[0,"(a) Classes of aliens ineligible for visas or admission"],[0,"Except as otherwise provided in this chapter, aliens who are inadmissible under the following paragraphs are ineligible to receive visas and ineligible to be admitted to the United States:"],[0,"(1) Health-related grounds"],[0,"(A) In general"],[2,"Any alien—"],[3,"(i) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services) to have a communicable disease of public health significance; 1"],[3,"(ii) except as provided in subparagraph (C), who seeks admission as an immigrant, or who seeks adjustment of status to the status of an alien lawfully admitted for permanent residence, and who has failed to present documentation of having received vaccination against vaccine-preventable diseases, which shall include at least the following diseases: mumps, measles, rubella, polio, tetanus and diphtheria toxoids, pertussis, influenza type B and hepatitis B, and any other vaccinations against vaccine-preventable diseases recommended by the Advisory Committee for Immunization Practices,"],[3,"(iii) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services in consultation with the Attorney General)—"],[4,"(I) to have a physical or mental disorder and behavior associated with the disorder that may pose, or has posed, a threat to the property, safety, or welfare of the alien or others, or"],[4,"(II) to have had a physical or mental disorder and a history of behavior associated with the disorder, which behavior has posed a threat to the property, safety, or welfare of the alien or others and which behavior is likely to recur or to lead to other harmful behavior, or"],[3,"(iv) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services) to be a drug abuser or addict,"],[2,"is inadmissible."],[0,"(B) Waiver authorized"],[2,"For provision authorizing waiver of certain clauses of subparagraph (A), see subsection (g)."],[0,"(C) Exception from immunization requirement for adopted children 10 years of age or younger"],[2,"Clause (ii) of subparagraph (A) shall not apply to a child who—"],[3,"(i) is 10 years of age or younger,"],[3,"(ii) is described in subparagraph (F) or (G) of section 1101(b)(1) of this title; 1 and"],[3,"(iii) is seeking an immigrant visa as an immediate relative under section 1151(b) of this title,"],[2,"if, prior to the admission of the child, an adoptive parent or prospective adoptive parent of the child, who has sponsored the child for admission as an immediate relative, has executed an affidavit stating that the parent is aware of the provisions of subparagraph (A)(ii) and will ensure that, within 30 days of the child's admission, or at the earliest time that is medically appropriate, the child will receive the vaccinations identified in such subparagraph."],[0,"(2) Criminal and related grounds"],[0,"(A) Conviction of certain crimes"],[0,"(i) In general"],[3,"Except as provided in clause (ii), any alien convicted of, or who admits having committed, or who admits committing acts which constitute the essential elements of—"],[4,"(I) a crime involving moral turpitude (other than a purely political offense) or an attempt or conspiracy to commit such a crime, or"],[4,"(II) a violation of (or a conspiracy or attempt to violate) any law or regulation of a State, the United States, or a foreign country relating to a controlled substance (as defined in section 802 of title 21),"],[0,"is inadmissible."],[0,"(ii) Exception"],[3,"Clause (i)(I) shall not apply to an alien who committed only one crime if—"],[4,"(I) the crime was committed when the alien was under 18 years of age, and the crime was committed (and the alien released from any confinement to a prison or correctional institution imposed for the crime) more than 5 years before the date of application for a visa or other documentation and the date of application for admission to the United States, or"],[4,"(II) the maximum penalty possible for the crime of which the alien was convicted (or which the alien admits having committed or of which the acts that the alien admits having committed constituted the essential elements) did not exceed imprisonment for one year and, if the alien was convicted of such crime, the alien was not sentenced to a term of imprisonment in excess of 6 months (regardless of the extent to which the sentence was ultimately executed)."],[0,"(B) Multiple criminal convictions"],[2,"Any alien convicted of 2 or more offenses (other than purely political offenses), regardless of whether the conviction was in a single trial or whether the offenses arose from a single scheme of misconduct and regardless of whether the offenses involved moral turpitude, for which the aggregate sentences to confinement were 5 years or more is inadmissible."],[0,"(C) Controlled substance traffickers"],[2,"Any alien who the consular officer or the Attorney General knows or has reason to believe—"],[3,"(i) is or has been an illicit trafficker in any controlled substance or in any listed chemical (as defined in section 802 of title 21), or is or has been a knowing aider, abettor, assister, conspirator, or colluder with others in the illicit trafficking in any such controlled or listed substance or chemical, or endeavored to do so; or"],[3,"(ii) is the spouse, son, or daughter of an alien inadmissible under clause (i), has, within the previous 5 years, obtained any financial or other benefit from the illicit activity of that alien, and knew or reasonably should have known that the financial or other benefit was the product of such illicit activity,"],[2,"is inadmissible."],[0,"(D) Prostitution and commercialized vice"],[2,"Any alien who—"],[3,"(i) is coming to the United States solely, principally, or incidentally to engage in prostitution, or has engaged in prostitution within 10 years of the date of application for a visa, admission, or adjustment of status,"],[3,"(ii) directly or indirectly procures or attempts to procure, or (within 10 years of the date of application for a visa, admission, or adjustment of status) procured or attempted to procure or to import, prostitutes or persons for the purpose of prostitution, or receives or (within such 10-year period) received, in whole or in part, the proceeds of prostitution, or"],[3,"(iii) is coming to the United States to engage in any other unlawful commercialized vice, whether or not related to prostitution,"],[2,"is inadmissible."],[0,"(E) Certain aliens involved in serious criminal activity who have asserted immunity from prosecution"],[2,"Any alien—"],[3,"(i) who has committed in the United States at any time a serious criminal offense (as defined in section 1101(h) of this title),"],[3,"(ii) for whom immunity from criminal jurisdiction was exercised with respect to that offense,"],[3,"(iii) who as a consequence of the offense and exercise of immunity has departed from the United States, and"],[3,"(iv) who has not subsequently submitted fully to the jurisdiction of the court in the United States having jurisdiction with respect to that offense,"],[2,"is inadmissible."],[0,"(F) Waiver authorized"],[2,"For provision authorizing waiver of certain subparagraphs of this paragraph, see subsection (h)."],[0,"(G) Foreign government officials who have committed particularly severe violations of religious freedom"],[2,"Any alien who, while serving as a foreign government official, was responsible for or directly carried out, at any time, particularly severe violations of religious freedom, as defined in section 6402 of title 22, is inadmissible."],[0,"(H) Significant traffickers in persons"],[0,"(i) In general"],[3,"Any alien who commits or conspires to commit human trafficking offenses in the United States or outside the United States, or who the consular officer, the Secretary of Homeland Security, the Secretary of State, or the Attorney General knows or has reason to believe is or has been a knowing aider, abettor, assister, conspirator, or colluder with such a trafficker in severe forms of trafficking in persons, as defined in the section 7102 of title 22, is inadmissible."],[0,"(ii) Beneficiaries of trafficking"],[3,"Except as provided in clause (iii), any alien who the consular officer or the Attorney General knows or has reason to believe is the spouse, son, or daughter of an alien inadmissible under clause (i), has, within the previous 5 years, obtained any financial or other benefit from the illicit activity of that alien, and knew or reasonably should have known that the financial or other benefit was the product of such illicit activity, is inadmissible."],[0,"(iii) Exception for certain sons and daughters"],[3,"Clause (ii) shall not apply to a son or daughter who was a child at the time he or she received the benefit described in such clause."],[0,"(I) Money laundering"],[2,"Any alien—"],[3,"(i) who a consular officer or the Attorney General knows, or has reason to believe, has engaged, is engaging, or seeks to enter the United States to engage, in an offense which is described in section 1956 or 1957 of title 18 (relating to laundering of monetary instruments); or"],[3,"(ii) who a consular officer or the Attorney General knows is, or has been, a knowing aider, abettor, assister, conspirator, or colluder with others in an offense which is described in such section;"],[2,"is inadmissible."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1182?type=usc&year=mostrecent&link-type=html"},"by":{"0":"3, 26, 3"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"for urgent humanitarian reasons or signifcant public beneft.","cite":"8 U. S. C. § 1182(d)(5)(A)"}]},{"t":"usc","label":"8 U.S.C. § 1225","url":"https://www.law.cornell.edu/uscode/text/8/1225","subs":["(b)(1)","(b)(1)(A)(i)","(b)(1)(A)(ii)","(b)(1)(A)(iii)","(b)(1)(B)","(b)(1)(B)(ii)","(b)(1)(B)(iii)","(b)(1)(B)(iii)(I)","(b)(1)(B)(iii)(II)","(b)(1)(B)(iii)(III)","(b)(1)(B)(iii)(IV)","(b)(1)(B)(v)","(b)(1)(E)(i)"],"stext":{"head":"§1225. Inspection by immigration officers; expedited removal of inadmissible arriving aliens; referral for hearing","paras":[[0,"(a) Inspection"],[0,"(1) Aliens treated as applicants for admission"],[1,"An alien present in the United States who has not been admitted or who arrives in the United States (whether or not at a designated port of arrival and including an alien who is brought to the United States after having been interdicted in international or United States waters) shall be deemed for purposes of this chapter an applicant for admission."],[0,"(2) Stowaways"],[1,"An arriving alien who is a stowaway is not eligible to apply for admission or to be admitted and shall be ordered removed upon inspection by an immigration officer. Upon such inspection if the alien indicates an intention to apply for asylum under section 1158 of this title or a fear of persecution, the officer shall refer the alien for an interview under subsection (b)(1)(B). A stowaway may apply for asylum only if the stowaway is found to have a credible fear of persecution under subsection (b)(1)(B). In no case may a stowaway be considered an applicant for admission or eligible for a hearing under section 1229a of this title."],[0,"(3) Inspection"],[1,"All aliens (including alien crewmen) who are applicants for admission or otherwise seeking admission or readmission to or transit through the United States shall be inspected by immigration officers."],[0,"(4) Withdrawal of application for admission"],[1,"An alien applying for admission may, in the discretion of the Attorney General and at any time, be permitted to withdraw the application for admission and depart immediately from the United States."],[0,"(5) Statements"],[1,"An applicant for admission may be required to state under oath any information sought by an immigration officer regarding the purposes and intentions of the applicant in seeking admission to the United States, including the applicant's intended length of stay and whether the applicant intends to remain permanently or become a United States citizen, and whether the applicant is inadmissible."],[0,"(b) Inspection of applicants for admission"],[0,"(1) Inspection of aliens arriving in the United States and certain other aliens who have not been admitted or paroled"],[0,"(A) Screening"],[0,"(i) In general"],[3,"If an immigration officer determines that an alien (other than an alien described in subparagraph (F)) who is arriving in the United States or is described in clause (iii) is inadmissible under section 1182(a)(6)(C) or 1182(a)(7) of this title, the officer shall order the alien removed from the United States without further hearing or review unless the alien indicates either an intention to apply for asylum under section 1158 of this title or a fear of persecution."],[0,"(ii) Claims for asylum"],[3,"If an immigration officer determines that an alien (other than an alien described in subparagraph (F)) who is arriving in the United States or is described in clause (iii) is inadmissible under section 1182(a)(6)(C) or 1182(a)(7) of this title and the alien indicates either an intention to apply for asylum under section 1158 of this title or a fear of persecution, the officer shall refer the alien for an interview by an asylum officer under subparagraph (B)."],[0,"(iii) Application to certain other aliens"],[0,"(I) In general"],[4,"The Attorney General may apply clauses (i) and (ii) of this subparagraph to any or all aliens described in subclause (II) as designated by the Attorney General. Such designation shall be in the sole and unreviewable discretion of the Attorney General and may be modified at any time."],[0,"(II) Aliens described"],[4,"An alien described in this clause is an alien who is not described in subparagraph (F), who has not been admitted or paroled into the United States, and who has not affirmatively shown, to the satisfaction of an immigration officer, that the alien has been physically present in the United States continuously for the 2-year period immediately prior to the date of the determination of inadmissibility under this subparagraph."],[0,"(B) Asylum interviews"],[0,"(i) Conduct by asylum officers"],[3,"An asylum officer shall conduct interviews of aliens referred under subparagraph (A)(ii), either at a port of entry or at such other place designated by the Attorney General."],[0,"(ii) Referral of certain aliens"],[3,"If the officer determines at the time of the interview that an alien has a credible fear of persecution (within the meaning of clause (v)), the alien shall be detained for further consideration of the application for asylum."],[0,"(iii) Removal without further review if no credible fear of persecution"],[0,"(I) In general"],[4,"Subject to subclause (III), if the officer determines that an alien does not have a credible fear of persecution, the officer shall order the alien removed from the United States without further hearing or review."],[0,"(II) Record of determination"],[4,"The officer shall prepare a written record of a determination under subclause (I). Such record shall include a summary of the material facts as stated by the applicant, such additional facts (if any) relied upon by the officer, and the officer's analysis of why, in the light of such facts, the alien has not established a credible fear of persecution. A copy of the officer's interview notes shall be attached to the written summary."],[0,"(III) Review of determination"],[4,"The Attorney General shall provide by regulation and upon the alien's request for prompt review by an immigration judge of a determination under subclause (I) that the alien does not have a credible fear of persecution. Such review shall include an opportunity for the alien to be heard and questioned by the immigration judge, either in person or by telephonic or video connection. Review shall be concluded as expeditiously as possible, to the maximum extent practicable within 24 hours, but in no case later than 7 days after the date of the determination under subclause (I)."],[0,"(IV) Mandatory detention"],[4,"Any alien subject to the procedures under this clause shall be detained pending a final determination of credible fear of persecution and, if found not to have such a fear, until removed."],[0,"(iv) Information about interviews"],[3,"The Attorney General shall provide information concerning the asylum interview described in this subparagraph to aliens who may be eligible. An alien who is eligible for such interview may consult with a person or persons of the alien's choosing prior to the interview or any review thereof, according to regulations prescribed by the Attorney General. Such consultation shall be at no expense to the Government and shall not unreasonably delay the process."],[0,"(v) \"Credible fear of persecution\" defined"],[3,"For purposes of this subparagraph, the term \"credible fear of persecution\" means that there is a significant possibility, taking into account the credibility of the statements made by the alien in support of the alien's claim and such other facts as are known to the officer, that the alien could establish eligibility for asylum under section 1158 of this title."],[0,"(C) Limitation on administrative review"],[2,"Except as provided in subparagraph (B)(iii)(III), a removal order entered in accordance with subparagraph (A)(i) or (B)(iii)(I) is not subject to administrative appeal, except that the Attorney General shall provide by regulation for prompt review of such an order under subparagraph (A)(i) against an alien who claims under oath, or as permitted under penalty of perjury under section 1746 of title 28, after having been warned of the penalties for falsely making such claim under such conditions, to have been lawfully admitted for permanent residence, to have been admitted as a refugee under section 1157 of this title, or to have been granted asylum under section 1158 of this title."],[0,"(D) Limit on collateral attacks"],[2,"In any action brought against an alien under section 1325(a) of this title or section 1326 of this title, the court shall not have jurisdiction to hear any claim attacking the validity of an order of removal entered under subparagraph (A)(i) or (B)(iii)."],[0,"(E) \"Asylum officer\" defined"],[2,"As used in this paragraph, the term \"asylum officer\" means an immigration officer who—"],[3,"(i) has had professional training in country conditions, asylum law, and interview techniques comparable to that provided to full-time adjudicators of applications under section 1158 of this title, and"],[3,"(ii) is supervised by an officer who meets the condition described in clause (i) and has had substantial experience adjudicating asylum applications."],[0,"(F) Exception"],[2,"Subparagraph (A) shall not apply to an alien who is a native or citizen of a country in the Western Hemisphere with whose government the United States does not have full diplomatic relations and who arrives by aircraft at a port of entry."],[0,"(G) Commonwealth of the Northern Mariana Islands"],[2,"Nothing in this subsection shall be construed to authorize or require any person described in section 1158(e) of this title to be permitted to apply for asylum under section 1158 of this title at any time before January 1, 2014."],[0,"(2) Inspection of other aliens"],[0,"(A) In general"],[2,"Subject to subparagraphs (B) and (C), in the case of an alien who is an applicant for admission, if the examining immigration officer determines that an alien seeking admission is not clearly and beyond a doubt entitled to be admitted, the alien shall be detained for a proceeding under section 1229a of this title."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1225?type=usc&year=mostrecent&link-type=html"},"by":{"0":"9, 10, 9, 10, 9, 10, 9, 10, 9, 10, 9, 10, 9, 10, 9, 10, 9, 10, 9, 10, 9, 10, 9, 10","1":"4, 4, 4, 4, 7, 7","2":"1, 21, 1, 1, 9, 22, 19, 20"},"q":[{"src":"brief","b":0,"text":"shall include an opportunity for the alien to be heard and questioned by the","cite":"8 U.S.C. 1225(b)(1)(B)(iii)(III)"}]},{"t":"usc","label":"8 U.S.C. § 1229","url":"https://www.law.cornell.edu/uscode/text/8/1229","subs":["(a)"],"by":{"0":"9, 10"}},{"t":"usc","label":"8 U.S.C. § 1229a","url":"https://www.law.cornell.edu/uscode/text/8/1229a","subs":["(c)(5)"],"by":{"0":"passim, 43","2":"22"}},{"t":"usc","label":"8 U.S.C. § 1231","url":"https://www.law.cornell.edu/uscode/text/8/1231","subs":["(b)(3)","(b)(3)(A)"],"stext":{"head":"§1231. Detention and removal of aliens ordered removed","paras":[[0,"(a) Detention, release, and removal of aliens ordered removed"],[0,"(1) Removal period"],[0,"(A) In general"],[2,"Except as otherwise provided in this section, when an alien is ordered removed, the Attorney General shall remove the alien from the United States within a period of 90 days (in this section referred to as the \"removal period\")."],[0,"(B) Beginning of period"],[2,"The removal period begins on the latest of the following:"],[3,"(i) The date the order of removal becomes administratively final."],[3,"(ii) If the removal order is judicially reviewed and if a court orders a stay of the removal of the alien, the date of the court's final order."],[3,"(iii) If the alien is detained or confined (except under an immigration process), the date the alien is released from detention or confinement."],[0,"(C) Suspension of period"],[2,"The removal period shall be extended beyond a period of 90 days and the alien may remain in detention during such extended period if the alien fails or refuses to make timely application in good faith for travel or other documents necessary to the alien's departure or conspires or acts to prevent the alien's removal subject to an order of removal."],[0,"(2) Detention"],[1,"During the removal period, the Attorney General shall detain the alien. Under no circumstance during the removal period shall the Attorney General release an alien who has been found inadmissible under section 1182(a)(2) or 1182(a)(3)(B) of this title or deportable under section 1227(a)(2) or 1227(a)(4)(B) of this title."],[0,"(3) Supervision after 90-day period"],[1,"If the alien does not leave or is not removed within the removal period, the alien, pending removal, shall be subject to supervision under regulations prescribed by the Attorney General. The regulations shall include provisions requiring the alien—"],[2,"(A) to appear before an immigration officer periodically for identification;"],[2,"(B) to submit, if necessary, to a medical and psychiatric examination at the expense of the United States Government;"],[2,"(C) to give information under oath about the alien's nationality, circumstances, habits, associations, and activities, and other information the Attorney General considers appropriate; and"],[2,"(D) to obey reasonable written restrictions on the alien's conduct or activities that the Attorney General prescribes for the alien."],[0,"(4) Aliens imprisoned, arrested, or on parole, supervised release, or probation"],[0,"(A) In general"],[2,"Except as provided in section 259(a) 1 of title 42 and paragraph (2),2 the Attorney General may not remove an alien who is sentenced to imprisonment until the alien is released from imprisonment. Parole, supervised release, probation, or possibility of arrest or further imprisonment is not a reason to defer removal."],[0,"(B) Exception for removal of nonviolent offenders prior to completion of sentence of imprisonment"],[2,"The Attorney General is authorized to remove an alien in accordance with applicable procedures under this chapter before the alien has completed a sentence of imprisonment—"],[3,"(i) in the case of an alien in the custody of the Attorney General, if the Attorney General determines that (I) the alien is confined pursuant to a final conviction for a nonviolent offense (other than an offense related to smuggling or harboring of aliens or an offense described in section 1101(a)(43)(B), (C), (E), (I), or (L) of this title 3 and (II) the removal of the alien is appropriate and in the best interest of the United States; or"],[3,"(ii) in the case of an alien in the custody of a State (or a political subdivision of a State), if the chief State official exercising authority with respect to the incarceration of the alien determines that (I) the alien is confined pursuant to a final conviction for a nonviolent offense (other than an offense described in section 1101(a)(43)(C) or (E) of this title), (II) the removal is appropriate and in the best interest of the State, and (III) submits a written request to the Attorney General that such alien be so removed."],[0,"(C) Notice"],[2,"Any alien removed pursuant to this paragraph shall be notified of the penalties under the laws of the United States relating to the reentry of deported aliens, particularly the expanded penalties for aliens removed under subparagraph (B)."],[0,"(D) No private right"],[2,"No cause or claim may be asserted under this paragraph against any official of the United States or of any State to compel the release, removal, or consideration for release or removal of any alien."],[0,"(5) Reinstatement of removal orders against aliens illegally reentering"],[1,"If the Attorney General finds that an alien has reentered the United States illegally after having been removed or having departed voluntarily, under an order of removal, the prior order of removal is reinstated from its original date and is not subject to being reopened or reviewed, the alien is not eligible and may not apply for any relief under this chapter, and the alien shall be removed under the prior order at any time after the reentry."],[0,"(6) Inadmissible or criminal aliens"],[1,"An alien ordered removed who is inadmissible under section 1182 of this title, removable under section 1227(a)(1)(C), 1227(a)(2), or 1227(a)(4) of this title or who has been determined by the Attorney General to be a risk to the community or unlikely to comply with the order of removal, may be detained beyond the removal period and, if released, shall be subject to the terms of supervision in paragraph (3)."],[0,"(7) Employment authorization"],[1,"No alien ordered removed shall be eligible to receive authorization to be employed in the United States unless the Attorney General makes a specific finding that—"],[2,"(A) the alien cannot be removed due to the refusal of all countries designated by the alien or under this section to receive the alien, or"],[2,"(B) the removal of the alien is otherwise impracticable or contrary to the public interest."],[0,"(b) Countries to which aliens may be removed"],[0,"(1) Aliens arriving at the United States"],[1,"Subject to paragraph (3)—"],[0,"(A) In general"],[2,"Except as provided by subparagraphs (B) and (C), an alien who arrives at the United States and with respect to whom proceedings under section 1229a of this title were initiated at the time of such alien's arrival shall be removed to the country in which the alien boarded the vessel or aircraft on which the alien arrived in the United States."],[0,"(B) Travel from contiguous territory"],[2,"If the alien boarded the vessel or aircraft on which the alien arrived in the United States in a foreign territory contiguous to the United States, an island adjacent to the United States, or an island adjacent to a foreign territory contiguous to the United States, and the alien is not a native, citizen, subject, or national of, or does not reside in, the territory or island, removal shall be to the country in which the alien boarded the vessel that transported the alien to the territory or island."],[0,"(C) Alternative countries"],[2,"If the government of the country designated in subparagraph (A) or (B) is unwilling to accept the alien into that country's territory, removal shall be to any of the following countries, as directed by the Attorney General:"],[3,"(i) The country of which the alien is a citizen, subject, or national."],[3,"(ii) The country in which the alien was born."],[3,"(iii) The country in which the alien has a residence."],[3,"(iv) A country with a government that will accept the alien into the country's territory if removal to each country described in a previous clause of this subparagraph is impracticable, inadvisable, or impossible."],[0,"(2) Other aliens"],[1,"Subject to paragraph (3)—"],[0,"(A) Selection of country by alien"],[2,"Except as otherwise provided in this paragraph—"],[3,"(i) any alien not described in paragraph (1) who has been ordered removed may designate one country to which the alien wants to be removed, and"],[3,"(ii) the Attorney General shall remove the alien to the country the alien so designates."],[0,"(B) Limitation on designation"],[2,"An alien may designate under subparagraph (A)(i) a foreign territory contiguous to the United States, an adjacent island, or an island adjacent to a foreign territory contiguous to the United States as the place to which the alien is to be removed only if the alien is a native, citizen, subject, or national of, or has resided in, that designated territory or island."],[0,"(C) Disregarding designation"],[2,"The Attorney General may disregard a designation under subparagraph (A)(i) if—"],[3,"(i) the alien fails to designate a country promptly;"],[3,"(ii) the government of the country does not inform the Attorney General finally, within 30 days after the date the Attorney General first inquires, whether the government will accept the alien into the country;"],[3,"(iii) the government of the country is not willing to accept the alien into the country; or"],[3,"(iv) the Attorney General decides that removing the alien to the country is prejudicial to the United States."],[0,"(D) Alternative country"],[2,"If an alien is not removed to a country designated under subparagraph (A)(i), the Attorney General shall remove the alien to a country of which the alien is a subject, national, or citizen unless the government of the country—"],[3,"(i) does not inform the Attorney General or the alien finally, within 30 days after the date the Attorney General first inquires or within another period of time the Attorney General decides is reasonable, whether the government will accept the alien into the country; or"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1231?type=usc&year=mostrecent&link-type=html"},"by":{"0":"7, 8, 35","1":"6","2":"6"}},{"t":"usc","label":"8 U.S.C. § 1252","url":"https://www.law.cornell.edu/uscode/text/8/1252","subs":["(a)","(a)(1)","(a)(2)(A)(i)","(e)","(e)(2)","(e)(3)","(e)(3)(A)","(e)(3)(B)","(e)(5)","(a)(2)(A)(iii)"],"stext":{"head":"§1252. Judicial review of orders of removal","paras":[[0,"(a) Applicable provisions"],[0,"(1) General orders of removal"],[1,"Judicial review of a final order of removal (other than an order of removal without a hearing pursuant to section 1225(b)(1) of this title) is governed only by chapter 158 of title 28, except as provided in subsection (b) and except that the court may not order the taking of additional evidence under section 2347(c) of such title."],[0,"(2) Matters not subject to judicial review"],[0,"(A) Review relating to section 1225(b)(1)"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, no court shall have jurisdiction to review—"],[3,"(i) except as provided in subsection (e), any individual determination or to entertain any other cause or claim arising from or relating to the implementation or operation of an order of removal pursuant to section 1225(b)(1) of this title,"],[3,"(ii) except as provided in subsection (e), a decision by the Attorney General to invoke the provisions of such section,"],[3,"(iii) the application of such section to individual aliens, including the determination made under section 1225(b)(1)(B) of this title, or"],[3,"(iv) except as provided in subsection (e), procedures and policies adopted by the Attorney General to implement the provisions of section 1225(b)(1) of this title."],[0,"(B) Denials of discretionary relief"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, and except as provided in subparagraph (D), and regardless of whether the judgment, decision, or action is made in removal proceedings, no court shall have jurisdiction to review—"],[3,"(i) any judgment regarding the granting of relief under section 1182(h), 1182(i), 1229b, 1229c, or 1255 of this title, or"],[3,"(ii) any other decision or action of the Attorney General or the Secretary of Homeland Security the authority for which is specified under this subchapter to be in the discretion of the Attorney General or the Secretary of Homeland Security, other than the granting of relief under section 1158(a) of this title."],[0,"(C) Orders against criminal aliens"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, and except as provided in subparagraph (D), no court shall have jurisdiction to review any final order of removal against an alien who is removable by reason of having committed a criminal offense covered in section 1182(a)(2) or 1227(a)(2)(A)(iii), (B), (C), or (D) of this title, or any offense covered by section 1227(a)(2)(A)(ii) of this title for which both predicate offenses are, without regard to their date of commission, otherwise covered by section 1227(a)(2)(A)(i) of this title."],[0,"(D) Judicial review of certain legal claims"],[2,"Nothing in subparagraph (B) or (C), or in any other provision of this chapter (other than this section) which limits or eliminates judicial review, shall be construed as precluding review of constitutional claims or questions of law raised upon a petition for review filed with an appropriate court of appeals in accordance with this section."],[0,"(3) Treatment of certain decisions"],[1,"No alien shall have a right to appeal from a decision of an immigration judge which is based solely on a certification described in section 1229a(c)(1)(B) of this title."],[0,"(4) Claims under the United Nations Convention"],[1,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, a petition for review filed with an appropriate court of appeals in accordance with this section shall be the sole and exclusive means for judicial review of any cause or claim under the United Nations Convention Against Torture and Other Forms of Cruel, Inhuman, or Degrading Treatment or Punishment, except as provided in subsection (e)."],[0,"(5) Exclusive means of review"],[1,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, a petition for review filed with an appropriate court of appeals in accordance with this section shall be the sole and exclusive means for judicial review of an order of removal entered or issued under any provision of this chapter, except as provided in subsection (e). For purposes of this chapter, in every provision that limits or eliminates judicial review or jurisdiction to review, the terms \"judicial review\" and \"jurisdiction to review\" include habeas corpus review pursuant to section 2241 of title 28, or any other habeas corpus provision, sections 1361 and 1651 of such title, and review pursuant to any other provision of law (statutory or nonstatutory)."],[0,"(b) Requirements for review of orders of removal"],[0,"With respect to review of an order of removal under subsection (a)(1), the following requirements apply:"],[0,"(1) Deadline"],[1,"The petition for review must be filed not later than 30 days after the date of the final order of removal."],[0,"(2) Venue and forms"],[1,"The petition for review shall be filed with the court of appeals for the judicial circuit in which the immigration judge completed the proceedings. The record and briefs do not have to be printed. The court of appeals shall review the proceeding on a typewritten record and on typewritten briefs."],[0,"(3) Service"],[0,"(A) In general"],[2,"The respondent is the Attorney General. The petition shall be served on the Attorney General and on the officer or employee of the Service in charge of the Service district in which the final order of removal under section 1229a of this title was entered."],[0,"(B) Stay of order"],[2,"Service of the petition on the officer or employee does not stay the removal of an alien pending the court's decision on the petition, unless the court orders otherwise."],[0,"(C) Alien's brief"],[2,"The alien shall serve and file a brief in connection with a petition for judicial review not later than 40 days after the date on which the administrative record is available, and may serve and file a reply brief not later than 14 days after service of the brief of the Attorney General, and the court may not extend these deadlines except upon motion for good cause shown. If an alien fails to file a brief within the time provided in this paragraph, the court shall dismiss the appeal unless a manifest injustice would result."],[0,"(4) Scope and standard for review"],[1,"Except as provided in paragraph (5)(B)—"],[2,"(A) the court of appeals shall decide the petition only on the administrative record on which the order of removal is based,"],[2,"(B) the administrative findings of fact are conclusive unless any reasonable adjudicator would be compelled to conclude to the contrary,"],[2,"(C) a decision that an alien is not eligible for admission to the United States is conclusive unless manifestly contrary to law, and"],[2,"(D) the Attorney General's discretionary judgment whether to grant relief under section 1158(a) of this title shall be conclusive unless manifestly contrary to the law and an abuse of discretion."],[1,"No court shall reverse a determination made by a trier of fact with respect to the availability of corroborating evidence, as described in section 1158(b)(1)(B), 1229a(c)(4)(B), or 1231(b)(3)(C) of this title, unless the court finds, pursuant to subsection (b)(4)(B), that a reasonable trier of fact is compelled to conclude that such corroborating evidence is unavailable."],[0,"(5) Treatment of nationality claims"],[0,"(A) Court determination if no issue of fact"],[2,"If the petitioner claims to be a national of the United States and the court of appeals finds from the pleadings and affidavits that no genuine issue of material fact about the petitioner's nationality is presented, the court shall decide the nationality claim."],[0,"(B) Transfer if issue of fact"],[2,"If the petitioner claims to be a national of the United States and the court of appeals finds that a genuine issue of material fact about the petitioner's nationality is presented, the court shall transfer the proceeding to the district court of the United States for the judicial district in which the petitioner resides for a new hearing on the nationality claim and a decision on that claim as if an action had been brought in the district court under section 2201 of title 28."],[0,"(C) Limitation on determination"],[2,"The petitioner may have such nationality claim decided only as provided in this paragraph."],[0,"(6) Consolidation with review of motions to reopen or reconsider"],[1,"When a petitioner seeks review of an order under this section, any review sought of a motion to reopen or reconsider the order shall be consolidated with the review of the order."],[0,"(7) Challenge to validity of orders in certain criminal proceedings"],[0,"(A) In general"],[2,"If the validity of an order of removal has not been judicially decided, a defendant in a criminal proceeding charged with violating section 1253(a) of this title may challenge the validity of the order in the criminal proceeding only by filing a separate motion before trial. The district court, without a jury, shall decide the motion before trial."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1252?type=usc&year=mostrecent&link-type=html"},"by":{"0":"26, 26, 26, 26, 26, 26, 26, 26, 26","1":"2, 4, 4","2":"2, 2, 3, 16, 20, 21, 1, 10, 21, 21, 10"},"q":[{"src":"brief","b":0,"text":"implement the provisions of section 1225(b)(1).","cite":"8 U.S.C. 1252(a)(2)(A)(i)"},{"src":"brief","b":0,"text":"the court’s inquiry shall be limited to whether such an order in fact was issued and whether it relates to the petitioner. There shall be no review of whether the alien is actually inadmissible or entitled to any relief from removal.","cite":"8 U.S.C. 1252(e)(5)"}]},{"t":"usc","label":"8 U.S.C. § 1324","url":"https://www.law.cornell.edu/uscode/text/8/1324","subs":["(a)(2)"],"by":{"0":"26"}},{"t":"usc","label":"8 U.S.C. § 1357","url":"https://www.law.cornell.edu/uscode/text/8/1357","subs":["(a)(3)"],"by":{"0":"26"}},{"t":"usc","label":"28 U.S.C. § 2241","url":"https://www.law.cornell.edu/uscode/text/28/2241","subs":["(c)(1)"],"by":{"0":"31","2":"10"}},{"t":"reg","label":"69 Fed. Reg. 48,877","url":"https://www.govinfo.gov/link/fr/69/48877","by":{"0":"6, 7, 47"}},{"t":"reg","label":"84 Fed. Reg. 33,829","url":"https://www.govinfo.gov/link/fr/84/33829","by":{"0":"8, 47, 48","2":"23"}},{"t":"reg","label":"84 Fed. Reg. 35,409","url":"https://www.govinfo.gov/link/fr/84/35409","by":{"0":"6"}},{"t":"case","label":"Balasubramanrim v. INS","cite":"143 F.3d 157","y":1998,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/143/157/","by":{"1":"7"}},{"t":"case","label":"Bridges v. Wixon","cite":"326 U.S. 135","y":1945,"id":"scdb/1944-064","sc":1,"by":{"1":"50"}},{"t":"case","label":"Chin Yow v. United States","cite":"208 U.S. 8","y":1908,"id":"scdb/1907-048","sc":1,"by":{"1":"25, 26, 30"},"q":[{"src":"argument","who":"Mr. Gelernt","text":"It was the Chin Yow case a few years later. And even before Ekiu was Jung Ah Lung. For the next 60 years in finality, reviewed those cases."}]},{"t":"case","label":"Delgadillo v. Carmichael","cite":"332 U.S. 388","y":1947,"id":"scdb/1947-003","sc":1,"by":{"1":"50"}},{"t":"case","label":"Gaksakuman v. U.S. Att’y Gen.","cite":"767 F.3d 1164","y":2014,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/767/1164/","by":{"1":"5"}},{"t":"case","label":"Gonzales v. Williams","cite":"192 U.S. 1","y":1904,"id":"scdb/1903-060","sc":1,"by":{"1":"15","2":"13"}},{"t":"case","label":"Hansen v. Haff","cite":"291 U.S. 559","y":1934,"id":"scdb/1933-050","sc":1,"by":{"1":"50"}},{"t":"case","label":"INS v. Chadha","cite":"462 U.S. 919","y":1983,"id":"1981/80-1832","sc":1,"by":{"1":"35, 48"}},{"t":"case","label":"Jones v. Cunningham","cite":"371 U.S. 236","y":1963,"id":"1962/77","sc":1,"by":{"1":"27"}},{"t":"case","label":"Kanaszczyc v. Mathews","cite":"30 F.2d 573","y":1929,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/30/573/","by":{"1":"16"}},{"t":"case","label":"MacKusick v. Johnson","cite":"3 F.2d 398","y":1924,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/3/398/","by":{"1":"30, 50"}},{"t":"case","label":"Martinez v. Neelly","cite":"344 U.S. 916","y":1953,"id":"scdb/1952-143","sc":1,"by":{"1":"17, 17, 18, 19, 22"},"q":[{"src":"brief","b":1,"text":"The clear purpose of this provision was to preclude judicial review of the Attorney General’s decisions in alien deportation cases insofar as the Congress could do so under the Constitution.","cite":"344 U.S. 916"}]},{"t":"case","label":"Mathews v. Diaz","cite":"426 U.S. 67","y":1976,"id":"1974/73-1046","sc":1,"by":{"1":"40"}},{"t":"case","label":"Moncrieffe v. Holder","cite":"569 U.S. 184","y":2013,"id":"2012/11-702","sc":1,"by":{"1":"23, 43"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"a greater likelihood of persecution or torture at home than is necessary for asylum.","cite":"569 U. S. 184, 187–188, n. 1"}]},{"t":"case","label":"Nken v. Holder","cite":"556 U.S. 418","y":2009,"id":"2008/08-681","sc":1,"by":{"1":"49"}},{"t":"case","label":"Omar v. McHugh","cite":"646 F.3d 13","y":2011,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/646/13/","by":{"1":"32, 33","2":"19"}},{"t":"case","label":"R. v. Clarkson","cite":"93 Eng. Rep. 625","y":1722,"court":"K.B.","url":"https://www.courtlistener.com/c/Eng.%20Rep./93/625/","by":{"1":"27"},"q":[{"src":"brief","b":1,"text":"The test used was simply whether she was ‘at her liberty to go where she please(d).’","cite":"93 Eng. Rep. 625"}]},{"t":"case","label":"R. v. Nathan","cite":"93 Eng. Rep. 914","y":1724,"court":"K.B.","url":"https://www.courtlistener.com/c/Eng.%20Rep./93/914/","by":{"1":"30"}},{"t":"case","label":"Rowoldt v. Perfetto","cite":"355 U.S. 115","y":1957,"id":"1957/5","sc":1,"by":{"1":"50"},"q":[{"src":"argument","who":"Mr. Gelernt","text":"That's the Rowoldt case, where the Court said: Look, you have to be meaningfully associated with the Communist Party, and then went on to look extensively at the facts."}]},{"t":"case","label":"Shelby County v. Holder","cite":"570 U.S. 529","y":2013,"id":"2012/12-96","sc":1,"by":{"1":"24"}},{"t":"case","label":"Tod v. Waldman","cite":"266 U.S. 113","y":1924,"id":"scdb/1924-028","sc":1,"by":{"1":"30"},"q":[{"src":"argument","who":"Mr. Gelernt","text":"Waldman. They came to this country seeking initial entry. The general admissibility rule was you had to be literate. The Jewish refugees in that case said: But I'm -- we are refugees; therefore, we can stay, notwithstanding being illiterate."},{"src":"argument","who":"Mr. Gelernt","text":"Waldman, even though the refugees were -- were illiterate and therefore inadmissible. They were excused from that. But the other point is that the Court throughout the finality era always reviewed whether they fell within the statute or not."}]},{"t":"case","label":"United States ex rel. Polymeris v. Trudell","cite":"284 U.S. 279","y":1932,"id":"scdb/1931-116","sc":1,"by":{"1":"15","2":"13"}},{"t":"case","label":"United States ex rel. Accardi v. Shaughnessy","cite":"347 U.S. 260","y":1954,"id":"1940-1955/347us260","sc":1,"by":{"1":"16, 20, 24","2":"13"},"q":[{"src":"argument","who":"Mr. Gelernt","text":"One is Accardi, decided the year after Heikkila v. Barber said the only review under this regime is that which is required by the Constitution."},{"src":"argument","who":"Mr. Gelernt","text":"That's the Accardi case, suspension of deportation, even though they were concededly removal. That's Tod v. Waldman, even though the refugees were -- were illiterate and therefore inadmissible."},{"src":"argument","who":"Justice Alito","text":"Other than Accardi and the other case you cited."}]},{"t":"case","label":"United States ex rel. Johnson v. Shaughnessy","cite":"336 U.S. 806","y":1949,"id":"scdb/1948-073","sc":1,"by":{"1":"15, 50","2":"13"}},{"t":"case","label":"United States v. Jung Ah Lung","cite":"124 U.S. 621","y":1888,"id":"scdb/1887-149","sc":1,"by":{"1":"12, 25"},"q":[{"src":"brief","b":1,"text":"was not restrained of his liberty","cite":"124 U.S. at 626"},{"src":"argument","who":"Mr. Gelernt","text":"And even before Ekiu was Jung Ah Lung. For the next 60 years in finality, reviewed those cases. And the other point I would make about that is, if the government's right that habeas doesn't even apply to deportation, then even lawful permanent residents would not be entitled to habeas --"}]},{"t":"case","label":"United States v. Vanbiervliet","cite":"284 U.S. 590","y":1931,"url":"https://supreme.justia.com/cases/federal/us/284/590/","sc":1,"by":{"1":"16","2":"14"},"q":[{"src":"brief","b":1,"text":"entered the United States . . . without immigration inspection and without an immigration visa.","cite":"284 U.S. 590"}]},{"t":"case","label":"Yee Won v. White","cite":"256 U.S. 399","y":1921,"id":"scdb/1920-102","sc":1,"by":{"1":"15","2":"13"}},{"t":"case","label":"Zadvydas v. Davis","cite":"533 U.S. 678","y":2001,"id":"2000/99-7791","sc":1,"by":{"1":"38, 40"}},{"t":"const","label":"Amendment V","clauses":[["grand-jury","Grand Jury Clause"],["double-jeopardy","Double Jeopardy Clause"],["self-incrimination","Self-Incrimination Clause"],["due-process-5","Due Process Clause (Fifth Amendment)"],["takings","Takings Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"1":"passim","2":"7"}},{"t":"const","label":"Article I, Section 9","clauses":[["habeas","Suspension Clause (Habeas Corpus)"],["attainder-ex-post-facto","Bills of Attainder and Ex Post Facto Laws"],["appropriations","Appropriations Clause"],["emoluments","Emoluments Clauses"]],"by":{"1":"passim"}},{"t":"reg","label":"8 C.F.R. § 208.30","url":"https://www.ecfr.gov/current/title-8/section-208.30","subs":["(d)","(d)(2)","(d)(4)","(d)(5)","(f)"],"by":{"1":"7, 5, 4, 5, 23"}},{"t":"case","label":"Demore v. Kim","cite":"538 U.S. 510","y":2003,"id":"2002/01-1491","sc":1,"by":{"2":"19"}},{"t":"case","label":"INS v. Stevic","cite":"467 U.S. 407","y":1984,"id":"1983/82-973","sc":1,"by":{"2":"6"}},{"t":"case","label":"Sale v. Haitian Ctrs. Council, Inc.","cite":"509 U.S. 155","y":1993,"id":"1992/92-344","sc":1,"by":{"2":"5"}},{"t":"case","label":"United States v. Di Re","cite":"332 U.S. 581","y":1948,"id":"scdb/1947-021","sc":1,"by":{"2":"2"},"q":[{"src":"brief","b":2,"text":"the strong presumption of constitutionality due to an Act of Congress.","cite":"332 U.S. 581, 585"}]},{"t":"case","label":"Wong Wing v. United States","cite":"163 U.S. 228","y":1896,"id":"1850-1900/163us228","sc":1,"by":{"2":"6"}}]};